"""Install and verify completed MiniLM assets and corresponding UI as one release."""
import json,zipfile
from pathlib import Path
with zipfile.ZipFile('training-cache/minilm-artifact/merchant-minilm-cpu.zip') as archive:
    archive.extractall('data/merchant-discovery-minilm')
p=Path('data/merchant-discovery-minilm/manifest.json')
meta=json.loads(p.read_text())
assert meta['rows']==110832 and meta.get('ui_check') and 'MiniLM' in meta['semantic_model']
meta['semantic_model']='CPU all-MiniLM-L6-v2 + 96D projection'
p.write_text(json.dumps(meta))
files=json.loads("{\"pricing/merchant_discovery_ui.py\":\"\\\"\\\"\\\"Merchant + Meaning: direct feedback discovery, separate from profile experiments.\\\"\\\"\\\"\\nimport hashlib,json,sqlite3,zlib\\nfrom pathlib import Path\\nimport numpy as np,streamlit as st\\nfrom pricing.merchant_reco import recommend\\n@st.cache_resource(max_entries=1,show_spinner=False)\\ndef assets(folder,revision):\\n    p=Path(folder)\\n    meta=json.loads((p/'manifest.json').read_text())\\n    return meta,np.load(p/'semantic.npy',mmap_mode='r'),np.load(p/'inventory.npy',mmap_mode='r')\\ndef cars(folder,positions):\\n    with sqlite3.connect(str(folder/'cars.sqlite')) as conn:\\n        return [json.loads(zlib.decompress(conn.execute('SELECT payload FROM cars WHERE position=?',(int(i),)).fetchone()[0])) for i in positions]\\ndef render(root):\\n    from pricing.studio_design import page_intro\\n    from pricing.garage_art import car_art\\n    folder=Path(root)/'data/merchant-discovery-minilm'\\n    path=folder/'manifest.json'\\n    page_intro('Drive Chemistry · Merchant + Meaning','Find your type, not a cluster','Five honest reactions. Cars that speak your language.','💚')\\n    if not path.exists():st.info('The merchant and semantic catalogue is being built offline. Existing profile models remain available.');return\\n    meta,semantic,inventory=assets(str(folder),path.stat().st_mtime_ns)\\n    st.caption('MiniLM description matching is active. Merchant-name extraction is being processed separately; merchant inventory links are not active in this release.')\\n    version=hashlib.sha256(path.read_bytes()).hexdigest()[:12]\\n    st.caption(meta.get('semantic_model','Text similarity'))\\n    st.caption(f\\\"{meta['rows']:,} historical cars · no account · merchant identities are inferred, not verified\\\")\\n    st.write('Rate these actual cars. Likes pull related cars closer; dislikes reduce their scores. The model keeps several interests separate, so liking a pickup and a convertible is allowed.')\\n    memory=st.session_state.setdefault('merchant_ratings_'+version,{})\\n    seeds=meta['seeds']\\n    labels={1:'1 · No thanks',2:'2 · Not my type',3:'3 · I like it',4:'4 · Love it'}\\n    for i,car in zip(seeds,cars(folder,seeds)):\\n        with st.container(border=True):\\n            car_art(car,compact=True)\\n            st.markdown(f\\\"### {int(car['year'])} {car.get('manufacturer','')} {car.get('model','')}\\\")\\n            st.write(f\\\"Historical asking price: ${car['price']:,.0f} · {int(car.get('odometer') or 0):,} miles\\\")\\n            rating=st.pills('Your reaction · '+str(i),list(labels),format_func=labels.get,key=f'merchant_rating_{version}_{i}')\\n            if rating is not None:memory[i]=rating\\n    st.progress(sum(i in memory for i in seeds)/len(seeds),text=f'{sum(i in memory for i in seeds)} of 5 cars rated')\\n    budget=None\\n    if st.checkbox('Limit by historical asking price',key='merchant_budget_enabled'):\\n        budget=st.number_input('Maximum historical asking price · USD',min_value=1000.,max_value=150000.,value=30000.,step=1000.)\\n    ready=all(i in memory for i in seeds) and any(v>=3 for v in memory.values())\\n    if st.button('Find cars for my taste',type='primary',disabled=not ready,key='merchant_find'):\\n        with st.spinner('Matching vehicle descriptions…'):\\n            st.session_state['merchant_result_'+version]=recommend(semantic,inventory,memory,meta['types'],np.array(meta['prices']),budget=budget)\\n    result=st.session_state.get('merchant_result_'+version)\\n    if result:\\n        st.markdown('## Your shortlist · strongest preference first')\\n        for n,(pos,car) in enumerate(zip(result['positions'],cars(folder,result['positions']))):\\n            with st.container(border=True):\\n                car_art(car,compact=True)\\n                st.markdown(f\\\"### {n+1}. {int(car['year'])} {car.get('manufacturer','')} {car.get('model','')}\\\")\\n                st.write(f\\\"Historical asking price: ${car['price']:,.0f} · {int(car.get('odometer') or 0):,} miles\\\")\\n                st.caption('Historical example, not live inventory or a current valuation.')\\n                with st.expander('Why this car?'):\\n                    st.write({'semantic_match':round(result['semantic'][n],3),'inventory_association':round(result['inventory'][n],3),'dislike_penalty':round(result['dislike_penalty'][n],3)})\\n                    st.caption('These are ranking signals, not probabilities. Merchant associations describe shared vehicle types, not verified buyer preferences.')\\n                    st.text(car.get('description',''))\\n                extra=st.pills('Refine my taste · '+str(pos),list(labels),format_func=labels.get,key=f'merchant_extra_{version}_{pos}')\\n                if extra is not None:memory[pos]=extra\\n        st.caption('Rate results, then press Find cars for my taste again to refine. Previously rated cars are excluded.')\\n    with st.expander('How it works · business explanation'):\\n        st.write('Vehicle descriptions provide meaning. Business domains first identify candidate passages; NER runs only around those domains, reusing cached passages. Missing identities remain unresolved, and their cars stay in the catalogue. Their inventories share model, make and body-type columns, allowing related vehicle types to connect across merchants. Unknown identities do not block recommendations.')\\n        st.write('Each liked car contributes an individual similarity signal. Dislikes apply a soft penalty, not an all-or-nothing veto. Results are sorted by descending hybrid preference score, with at most two cars of an exact make/model type.')\\n        st.write(f\\\"Merchant candidate groups: {meta['merchant_candidates']:,}. Linked adverts: {meta['linked_rows']:,}. These identities have not been independently verified.\\\")\\n    with st.expander('Technical method and evidence limits'):\\n        st.write('Full-catalogue vehicle descriptions are encoded offline with all-MiniLM-L6-v2, projected to 96 dimensions with truncated SVD. Stored document vectors are normalized; no text model is loaded in the app. Inventory counts are normalized per merchant and weighted by inverse merchant frequency, then mapped through a low-rank SVD baseline. Ranking weights are 80% semantic and 20% inventory where available; dislike similarity subtracts up to 35%. No permanent user profile or learned satisfaction probability is asserted.')\\n        st.write('Five single-like/multiple-dislike mechanical tests must produce distinct results before publication. There is no independent relevance benchmark or audited merchant-identity precision yet. Additional session ratings are used for refinement, not reported as an unbiased test.')\\n\",\"pricing/taste_garage_ui.py\":\"\\\"\\\"\\\"Ten honest judgments, a vehicle-only ranker, and a readable shortlist.\\\"\\\"\\\"\\nimport hashlib,json,logging\\nfrom datetime import date\\nfrom pathlib import Path\\nimport numpy as np\\nimport streamlit as st\\nfrom pricing.taste_ranking import load,records,train_rank,ndcg10,adjusted_price_features,active_catalogue_folder\\n\\nLABELS={1:'1 · 😣 No thanks',2:'2 · 🙁 Not my type',3:'3 · 🙂 I like it',4:'4 · 😍 Love it'}\\n\\n@st.cache_resource(max_entries=1,show_spinner=False)\\ndef catalogue(root,version,profile_count=10):return load(root,profile_count)\\n\\n@st.cache_resource(max_entries=1,show_spinner=False)\\ndef transport(root):\\n    from marketbridge.time_engine import TimeTransport\\n    return TimeTransport(root)\\n\\ndef price_view(root,car,when):\\n    from pricing.reference_prices import adjust_reference\\n    try:return adjust_reference(car,'ask',when,transport(str(root)))['price_usd']\\n    except (ValueError,OSError,KeyError,TypeError):return None\\n\\ndef car_details(root,car,when):\\n    mileage=f\\\"{int(car['odometer']):,} miles\\\" if car.get('odometer') is not None else 'mileage not supplied'\\n    st.write(' · '.join([mileage]+[str(car[k]).title() for k in ['type','transmission','fuel'] if car.get(k)]))\\n    value=price_view(root,car,when)\\n    if value is not None:st.markdown(f'**${value:,.0f}** · asking-price scenario for {when:%d %b %Y}')\\n    else:st.caption('Date-adjusted price unavailable for this historical car.')\\n    st.caption(f\\\"Original asking advert: ${car['price']:,.0f} · {str(car['observed_date'])[:10]}. Not a live offer.\\\")\\n\\ndef render(root):\\n    from marketbridge.time_engine import today\\n    from pricing.studio_design import page_intro,journey_steps\\n    from pricing.garage_art import car_art\\n    root=Path(root)\\n    if (root/'data/merchant-discovery-minilm/manifest.json').exists() and json.loads((root/'data/merchant-discovery-minilm/manifest.json').read_text()).get('ui_check'):\\n        engine=st.radio('Discovery approach',['Merchant + Meaning','Existing profile experiments'],horizontal=True,key='drive_discovery_engine')\\n        if engine=='Merchant + Meaning':\\n            from pricing.merchant_discovery_ui import render as render_merchant_discovery\\n            render_merchant_discovery(root);return\\n    page_intro('Your personal car discovery studio','Drive Chemistry','Rate a few cars. Find your type. Skip the awkward small talk.','💚')\\n    st.caption('Free to explore · No registration · Real historical cars, not live inventory')\\n    journey_steps([('Pick your pace','A quick taste test or a deeper dive.'),('Trust your gut','Four reactions. No car expertise required.'),('Explore your ten','See the cars, the prices and why they made it.')])\\n    st.session_state.setdefault('taste_model_choice','HDBSCAN')\\n    def choose_model(name):\\n        st.session_state['taste_model_choice']=name\\n        st.session_state['taste_kmeans_enabled']=name=='KMeans'\\n        st.session_state['taste_hdbscan_enabled']=name=='HDBSCAN'\\n    model_columns=st.columns(2)\\n    with model_columns[0]:\\n        st.checkbox('KMeans · quick taste groups',value=st.session_state['taste_model_choice']=='KMeans',key='taste_kmeans_enabled',on_change=choose_model,args=('KMeans',))\\n    with model_columns[1]:\\n        st.checkbox('HDBSCAN · density taste groups',value=st.session_state['taste_model_choice']=='HDBSCAN',key='taste_hdbscan_enabled',on_change=choose_model,args=('HDBSCAN',))\\n    st.caption('Choose one model at a time. Both models are retained; each keeps its own ratings.')\\n    if st.session_state['taste_model_choice']=='KMeans' and not (root/'data/taste-garage-kmeans/release-check.json').exists():\\n        st.info('KMeans is still being prepared. HDBSCAN remains available through its checkbox.');return\\n    tests={'Speed Date · 10 cars, no small talk':10,'The Long Drive · 25 cars, zero commitment':25}\\n    st.session_state.setdefault('taste_test_mode',next(iter(tests)))\\n    def choose_test(value):st.session_state['taste_test_mode']=value\\n    for col,(value,size) in zip(st.columns(2),tests.items()):\\n        with col:\\n            with st.container(border=True):\\n                st.markdown('**Speed Date**' if size==10 else '**The Long Drive**')\\n                st.caption('10 cars. No small talk.' if size==10 else '25 cars. Zero commitment.')\\n                st.button('Choose Speed Date · 10 cars' if size==10 else 'Choose The Long Drive · 25 cars',key=f'taste_choose_{size}',on_click=choose_test,args=(value,),type='primary' if st.session_state['taste_test_mode']==value else 'secondary',use_container_width=True)\\n    chosen=st.session_state['taste_test_mode']\\n    profile_count=tests[chosen]\\n    st.caption('Switch tests without losing your ratings. Both return up to ten recommendations from historical adverts, not live stock.')\\n    with st.expander('How Drive Chemistry picks your cars'):\\n        st.markdown('1. **Meet a few real cars.** Each represents a group with shared vehicle characteristics.\\\\n2. **React honestly.** 1 means no thanks; 4 means love it. Rate the whole car, including the price.\\\\n3. **Explore your shortlist.** Your likes and dislikes filter the catalogue; a ranking model selects up to ten cars.\\\\n4. **Check the fit.** Open “Why this car?” or rate the results to tell us how well we did.')\\n        st.caption('Speed Date uses 10 representative cars. The Long Drive uses 25 finer profiles. Neither promises a perfect match. Your reactions stay in this Streamlit session.')\\n    folder=active_catalogue_folder(root);path=folder/'manifest.json'\\n    if not path.exists():\\n        st.info('The original-data car profiles are being built offline. This panel will unlock when the tested catalogue is installed; no substitute or invented prototypes are shown.');return\\n    variant=folder/'profiles-25.json'\\n    revision=(str(folder),path.stat().st_mtime_ns,path.stat().st_size,variant.stat().st_mtime_ns if variant.exists() else 0)\\n    try:loaded=catalogue(str(root),revision,profile_count)\\n    except (ValueError,OSError,KeyError):st.warning('The recommendation catalogue could not be verified. Your pricing and comparison tools remain available.');return\\n    if loaded is None:\\n        st.info('The 25-car test is being prepared from the verified HDBSCAN hierarchy. Speed Date remains available.');return\\n    meta,arrays=loaded;version=hashlib.sha256((path.read_bytes()+(variant.read_bytes() if profile_count==25 else b'')+str(profile_count).encode())).hexdigest()[:12]\\n    mixed=meta.get('encoding_kind')=='lemon-textprice-onehot-umap-v1'\\n    onehot=mixed or meta.get('encoding_kind')=='common-onehot-v1'\\n    st.caption(f\\\"Your discovery catalogue · {meta['rows']:,} historical cars · {profile_count} cars to react to\\\")\\n    if meta.get('density_method')=='minibatch-kmeans-soft':st.caption('Quick Match · temporary soft MiniBatchKMeans profiles. Distance affinities, not density memberships.')\\n    mode=st.radio('Shortlist price date',['Today','Choose a date'],horizontal=True,key='taste_date_mode')\\n    when=today() if mode=='Today' else st.date_input('Show price scenarios for',value=today(),key='taste_date')\\n    st.markdown(f'## 1 · Meet your {profile_count} taste-test cars')\\n    st.write('Rate the whole car: Would you want something like this? Compare cars against your own taste, not against each other’s price alone.')\\n    rating_keys=[f'taste_rating_{version}_{i}' for i in range(profile_count)]\\n    count=sum(st.session_state.get(k) in LABELS for k in rating_keys)\\n    st.progress(count/profile_count,text=f'{count} of {profile_count} cars rated')\\n    from pricing.accessibility import announce\\n    announce(f'{count} of {profile_count} cars rated. '+('All cars rated.' if count==profile_count else f'{profile_count-count} reactions remaining.'))\\n    memory=st.session_state.setdefault('taste_rating_memory',{})\\n    for i,p in enumerate(meta['profiles']):\\n        # One pair per row preserves 1,2,3... when mobile stacks columns.\\n        if i%2==0:columns=st.columns(2)\\n        car=p['prototype']\\n        with columns[i%2]:\\n            with st.container(border=True,key=f'garage_taste_card_{profile_count}_{i}'):\\n                car_art(car)\\n                st.markdown(f\\\"### {i+1}. {int(car['year'])} {str(car.get('manufacturer') or 'Unspecified').title()} {car.get('model') or 'model not supplied'}\\\")\\n                st.caption(f\\\"Taste profile {i+1} · represents {p['cars']:,} historical cars\\\")\\n                car_details(root,car,when)\\n                if rating_keys[i] not in st.session_state and rating_keys[i] in memory:st.session_state[rating_keys[i]]=memory[rating_keys[i]]\\n                st.markdown('**Your reaction**')\\n                reaction_label=f\\\"Your reaction · car {i+1}: {int(car['year'])} {car.get('manufacturer') or 'Unspecified'} {car.get('model') or ''}\\\"\\n                st.pills(reaction_label,list(LABELS),selection_mode='single',format_func=LABELS.get,key=rating_keys[i],persist_state='session',label_visibility='collapsed')\\n                memory[rating_keys[i]]=st.session_state.get(rating_keys[i])\\n                with st.expander(f'Description & details · car {i+1}'):\\n                    st.caption('Short excerpt from the historical advert; source text is not independently verified.')\\n                    st.text(car.get('description') or 'Description not supplied.')\\n                    st.write({k:car.get(k) for k in ['condition','drive','cylinders','title_status','paint_color','state']})\\n    ratings=[st.session_state.get(k) for k in rating_keys]\\n    complete=all(r in LABELS for r in ratings)\\n    signature=json.dumps(['direct-ratings-cosine-descending-v8',st.session_state['taste_model_choice'],version,ratings,str(when)])\\n    different=len(set(ratings))>1 if complete else False\\n    has_like=any(r in (3,4) for r in ratings)\\n    if complete and not has_like:st.info('Choose I like it or Love it for at least one car so there is something to recommend.')\\n    if complete and not different:st.info('Give at least two cars different ratings so the model has an ordering to learn.')\\n    st.markdown('## 2 · Find your car chemistry')\\n    if not complete:st.caption(f'{profile_count-count} more reaction'+('s' if profile_count-count!=1 else '')+' to go. Your shortlist unlocks once every car has a rating.')\\n    if st.button('Find my ten cars →',type='primary',disabled=not complete or not different or not has_like,key='taste_train'):\\n        try:\\n            with st.spinner('Mixing your likes, dislikes and a little car chemistry…'):\\n                try:adjusted=adjusted_price_features(arrays['codes'],arrays['numeric'],meta['levels'],arrays['prices'],arrays['source_days'],when,transport(str(root)))\\n                except (ValueError,OSError,KeyError,TypeError):adjusted=np.full(meta['rows'],np.nan)\\n                result=train_rank(arrays['codes'],arrays['numeric'],meta['levels'],arrays['clusters'],ratings,[p['position'] for p in meta['profiles']],arrays['validation'],prices=arrays['prices'],adjusted_prices=adjusted,memberships=arrays.get('memberships'),medoid_distances=arrays.get('medoid_rmse',arrays.get('medoid_cosine',arrays.get('medoid_l2'))))\\n                result['adjusted_price_support']=int(np.isfinite(adjusted).sum())\\n            st.session_state['taste_result']=(signature,result)\\n        except ValueError as exc:\\n            logging.getLogger(__name__).exception('Drive Chemistry invalid ranking state')\\n            if str(exc).startswith('No cars pass'):\\n                st.info('No cars pass this combination of likes and dislikes. Your ratings are saved. Try liking another taste-test car or use The Long Drive for finer choices.')\\n            else:\\n                st.error('The shortlist could not be calculated. Your ratings are saved.')\\n                with st.expander('Error details for support'):st.text(str(exc))\\n            return\\n        except (OSError,RuntimeError,MemoryError) as exc:\\n            logging.getLogger(__name__).exception('Drive Chemistry ranking execution failed')\\n            st.error('The shortlist ran into a processing problem. Your ratings are saved; please retry.')\\n            with st.expander('Error details for support'):st.text(type(exc).__name__)\\n            return\\n    saved=st.session_state.get('taste_result')\\n    if saved and saved[0]!=signature:st.info('Your reactions changed. Press Find my ten cars to refresh the shortlist.');saved=None\\n    if saved:\\n        announce('Shortlist ready. '+str(len(saved[1]['positions']))+' historical cars found.')\\n        result=saved[1];st.markdown(f\\\"## Your {len(result['positions'])} · tyres optional, taste mandatory\\\")\\n        st.write('**Discovery order · more different picks first.** These ten passed your preference checks, then were sorted from most different to closest to a car you liked. This is exploration order, not a best-match ranking.')\\n        st.caption('Your ratings shaped this shortlist. Cars you rated are left out, so every pick is a new introduction. These are historical examples, not cars currently for sale.')\\n        cars=records(root,result['positions'])\\n        for rank,(position,car) in enumerate(zip(result['positions'],cars),1):\\n            profile=int(arrays['clusters'][position]);p=meta['profiles'][profile]\\n            membership=arrays.get('memberships')\\n            with st.container(border=True,key=f'garage_shortlist_{rank}'):\\n                car_art(car,compact=True)\\n                st.markdown(f\\\"### {rank}. {int(car['year'])} {str(car.get('manufacturer') or 'Unspecified').title()} {car.get('model') or 'model not supplied'}\\\")\\n                car_details(root,car,when)\\n                with st.expander(f'Why this car? · pick {rank}'):\\n                    if result.get('evidence'):\\n                        e=result['evidence'][rank-1]\\n                        st.write(f\\\"Your taste signals: +{e['positive']:.2f} from likes − {e['negative']:.2f} from dislikes = {e['signed']:+.2f}.\\\")\\n                        if 'liked_profile' in e:st.caption(f\\\"Nearest liked representative: Profile {e['liked_profile']+1} · cosine distance {e['liked_distance']:.3f}.\\\")\\n                        if 'disliked_profile' in e:st.caption(f\\\"Nearest disliked representative: Profile {e['disliked_profile']+1} · distance {e['disliked_distance']:.3f}. This car is closer to a liked representative.\\\")\\n                    if membership is not None:\\n                        weights=membership[position];top=np.argsort(-weights)[:3]\\n                        st.write('Related taste profiles: '+ ' · '.join(f'{j+1}: {weights[j]:.0%}' for j in top if weights[j]>.001))\\n                        st.caption(f'Unassigned membership: {max(0,1-float(weights.sum())):.0%}. Membership strengths are model affinities, not probabilities of liking this car.')\\n                    else:st.write(f'Related profile {profile+1}.')\\n                    if 'medoid_rmse' in arrays or 'medoid_cosine' in arrays or 'medoid_l2' in arrays:\\n                        distances=arrays.get('medoid_rmse',arrays.get('medoid_cosine',arrays.get('medoid_l2')))[position];near=np.argsort(distances)[:3]\\n                        st.caption('Nearest representatives · FAISS distance: '+ ' · '.join(f'Profile {j+1}: {distances[j]:.3f}' for j in near))\\n                        st.caption(('RMSE is sqrt(mean((x − y)²)) over catalogue-column-standardized features, without row unit normalization. Magnitude matters; this is not a dollar error.' if 'medoid_rmse' in arrays else 'Cosine distance is 1 minus cosine similarity. Lower means closer. No extra column StandardScaler is used.')+' Lower means closer; this is not a dollar error or probability.')\\n                    if arrays['noise'][position]:st.caption('Exploratory match: HDBSCAN treated this advert as density noise; its soft affinities remain available without forcing a hard assignment.')\\n                with st.expander(f'Original description & specifications · pick {rank}'):\\n                    st.caption('Short excerpt from the historical advert; source text is not independently verified.')\\n                    st.text(car.get('description') or 'Description not supplied.')\\n                    st.write({k:car.get(k) for k in ['condition','drive','cylinders','title_status','paint_color','state']})\\n        with st.expander('Model scorecard · what we measured'):\\n            a,b,c=st.columns(3)\\n            a.metric('Held-out NDCG@10 · inferred preferences',f\\\"{result['ndcg10']:.3f}\\\" if result['ndcg10'] is not None else 'Not defined')\\n            b.metric('Random-order baseline',f\\\"{result['random_ndcg10']:.3f}\\\" if result['random_ndcg10'] is not None else 'Not defined')\\n            c.metric('Actual ratings supplied',profile_count)\\n            st.info('The displayed list is reordered by highest cosine distance. NDCG below evaluates the underlying ranker before this presentation sort. This NDCG@10 measures agreement with soft preferences inferred from cluster memberships. Thousands of adverts still come from only the representative ratings you supplied. It is not measured customer satisfaction or proof the recommendations are good.')\\n        with st.expander('Did we find your type? · rate your shortlist'):\\n            values=[]\\n            feedback_id=hashlib.sha256(signature.encode()).hexdigest()[:12]\\n            for i,car in enumerate(cars):values.append(st.radio(f\\\"{i+1}. {int(car['year'])} {car.get('manufacturer')} {car.get('model')}\\\",list(LABELS),index=None,format_func=LABELS.get,horizontal=True,key=f'taste_feedback_{feedback_id}_{i}'))\\n            if all(v in LABELS for v in values) and len(set(values))>1:\\n                direct=ndcg10(np.array(values)-1,np.arange(len(cars),0,-1))\\n                st.metric('NDCG@10 against your additional ratings',f'{direct:.3f}')\\n                st.caption('Evaluates ordering within the displayed cars only. It does not measure catalogue-wide recall. This feedback is not used to train the displayed list.')\\n        with st.expander('Technical result'):\\n            st.json({k:v for k,v in result.items() if k not in ['positions','scores']},expanded=False)\\n    with st.expander('The business view · what Drive Chemistry does'):\\n        st.markdown('**A starting point for discovery.** Drive Chemistry turns a handful of reactions into a shortlist of historical asking adverts. It can help you explore styles, price levels and alternatives before a real vehicle search.')\\n        st.markdown('**Your taste, not a popularity contest.** Similar vehicle profiles share some of your rating signal. Likes add evidence; dislikes subtract it. Cars closer to a disliked representative than a liked one are excluded. A ranking model selects eligible cars; the current presentation then puts larger cosine distances first.')\\n        st.markdown('**Prices need context.** Displayed amounts are date-adjusted asking-price scenarios at the recorded mileage. They are not completed-sale values, binding offers or live inventory. Changing the date does not rebuild the taste profiles.')\\n        st.caption(f\\\"Catalogue: {meta['rows']:,} retained historical cars · {meta['density_clusters']} taste profiles · {meta['noise_fraction']:.1%} classified as density noise. Noise cars may still receive soft affinities.\\\")\\n        st.write('The profile catalogue is learned offline. Your reactions train only the session ranking; no account, demographic profile or other users’ ratings are used.')\\n    with st.expander('Under the hood · features, clustering and ranking'):\\n        st.markdown('**Vehicle representation.** Common categorical values become one-hot indicators; rare or unseen values share an Other bucket. Numeric features include year, log mileage, missing-value indicators, log November-2026 asking-price scenarios and a stored cross-fitted MiniLM description-price estimate. Raw text embeddings are not used for this catalogue.')\\n        if meta.get('density_method')=='minibatch-kmeans-soft':\\n            st.write('MiniBatchKMeans fits 10 or 25 groups in balanced Euclidean vehicle features. The real assigned car nearest each center is shown. Soft affinities use the three nearest centers: exp(-distance² / (2 × temperature²)), normalized across those centers. Temperature is fitted offline from the median nearest/second-nearest squared-distance gap. These are similarity weights, not probabilities or HDBSCAN density memberships.')\\n        elif meta.get('density_method')=='direct-weighted-euclidean':\\n            st.write(meta['method_description'])\\n        elif meta.get('density_method')=='direct-weighted-manhattan':\\n            st.markdown('**Soft profiles.** HDBSCAN is fitted directly to these features using weighted Manhattan distance: 50% categorical mismatch rate plus 50% mean absolute numeric difference after frozen robust range scaling. One-hot swaps are counted once per field. There is no dimensionality reduction in this release. The 10- and 25-profile tests use cuts of the fitted density hierarchy.')\\n        else:\\n            st.write(meta.get('method_description','See the installed catalogue metadata for its clustering method.'))\\n        st.markdown('**Personal preference.** Direct ratings 1, 2, 3, 4 become signed evidence −1.5, −0.5, +0.5, +1.5. No inverse-rating transform or session scaler is applied. Soft cluster evidence has 75% weight; representative-distance affinity has 25%. Unassigned membership adds no evidence. Candidates need positive net evidence and must be nearer to a liked than a disliked representative when both exist.')\\n        st.markdown('**Similarity and display.** FAISS computes exact cosine distance on the existing encoded feature vectors, without an added feature-column StandardScaler. L2 normalization is used only to calculate cosine. Distance is 1 minus cosine similarity: smaller means closer. The selected shortlist is displayed in descending distance to the nearest liked representative, as a discovery order.')\\n        st.code('XGBRanker(objective=\\\"rank:ndcg\\\", eval_metric=\\\"ndcg@10\\\",\\\\n          tree_method=\\\"hist\\\", enable_categorical=True,\\\\n          max_depth=3, n_jobs=2)')\\n        st.write('XGBoost learns a vehicle-only ordering from inherited preference evidence, original log asking prices and supported date-adjusted log-price scenarios. User IDs, demographics, cluster IDs and prototype IDs are not predictors. Each advert appears once. A deterministic vehicle-ID split holds out roughly 20% for early stopping; prototypes stay in training, then the final ranker fits the full catalogue. Selected cars are reordered for display afterwards.')\\n    with st.expander('Evidence & limits · how to judge the results'):\\n        st.write('NDCG in the scorecard measures agreement with preferences inferred from the same representative ratings. It evaluates the ranker before the display sort; it does not establish customer satisfaction, catalogue-wide recall or commercial accuracy.')\\n        st.write('The feature vocabulary and numeric ranges use the reference catalogue. This is transductive exploration, not an independent external benchmark. Rare-category pooling and broad clusters can hide distinctions that matter to you. Rate the shortlist for a separate check of its displayed ordering; that feedback does not retrain the list you see.')\\n        st.caption('Historical data: Craigslist Used Cars, Tom / Zenodo 10457828, CC BY 4.0. Date scenarios use the saved depreciation curves and CPI/Holt market clock. Historical seller claims and vehicle condition are not independently verified.')\\n\",\"app.py\":\"\\\"\\\"\\\"Run with: python -m streamlit run app.py\\\"\\\"\\\"\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport streamlit as st\\nMODEL_ID = \\\"sentence-transformers/all-MiniLM-L6-v2\\\"\\nMAX_CHARACTERS = 8000\\n\\nst.set_page_config(page_title='Car Price Studio · Less haggle. More signal.',page_icon=str(Path(__file__).parent/'assets/pricing-icon.png'),layout='wide',initial_sidebar_state='collapsed')\\nif st.query_params.get('accessibility_report') == '1':\\n    from pricing.accessibility_report import render as render_accessibility_report\\n    render_accessibility_report()\\n    st.stop()\\n\\n# Keep troubleshooting reachable without importing/loading any pricing models.\\nif st.query_params.get('connection_check') == '1':\\n    from pricing.analytics import render_connection_check\\n    render_connection_check()\\n    st.stop()\\n\\n@st.cache_resource(show_spinner=False)\\ndef _accessible_garage_release_v6():\\n    # Refresh presentation modules retained by long-lived serving workers.\\n    import importlib,sys\\n    for name in ('pricing.accessibility','pricing.studio_design','pricing.navigation','pricing.taste_garage_ui','pricing.current_tools'):\\n        module=sys.modules.get(name)\\n        if module is not None:importlib.reload(module)\\n    return True\\n_accessible_garage_release_v6()\\n\\nfrom pricing.studio_design import install_style,render_hero,section,empty_receipt,sidebar_receipt,footer\\ninstall_style()\\nrender_hero()\\nfrom pricing.navigation import render_navigation\\n_workspace=render_navigation()\\nif _workspace=='🚦 Pick your garage':\\n    @st.cache_resource(show_spinner=False)\\n    def _taste_garage_minilm_v27():\\n        import importlib\\n        for name in ('pricing.taste_ranking','pricing.merchant_discovery_ui','pricing.taste_garage_ui'):\\n            importlib.reload(importlib.import_module(name))\\n        return True\\n    _taste_garage_minilm_v27()\\n    from pricing.taste_garage_ui import render as render_taste_garage\\n    render_taste_garage(Path(__file__).parent)\\n    from pricing.ga_events import render_events\\n    render_events()\\n    footer()\\n    st.stop()\\nif _workspace=='🔎 Listing Inspector':\\n    @st.cache_resource(show_spinner=False)\\n    def _inspector_forecast_context_release_v2():\\n        # Refresh these lazily imported UI modules once per release, including\\n        # long-lived workers with Python imports from the previous deployment.\\n        import importlib\\n        for name in ('pricing.inspector_estimate','pricing.inspector_neighbours'):\\n            importlib.reload(importlib.import_module(name))\\n        return True\\n    _inspector_forecast_context_release_v2()\\n    from pricing.listing_inspector import render as render_inspector\\n    render_inspector(Path(__file__).parent)\\n    from pricing.ga_events import render_events\\n    render_events()\\n    footer()\\n    st.stop()\\nif _workspace in ['🚗 Price my car','🌳 Hierarchical model'] and (Path(__file__).parent/'models/xgboost-hierarchy/release.json').exists():\\n    from pricing.hierarchy_sparse_studio import render\\n    render(Path(__file__).parent)\\n    from pricing.ga_events import render_events\\n    render_events()\\n    footer()\\n    st.stop()\\nif _workspace=='🧠 The science':\\n    from pricing.hierarchy_sparse_studio import explain\\n    from pricing.analytics import render_privacy\\n    render_privacy()\\n    explain()\\n    footer()\\n    st.stop()\\nif _workspace=='📅 Value over time':\\n    from pricing.current_tools import render_timeline\\n    from pricing.analytics import render_privacy\\n    render_privacy()\\n    render_timeline(Path(__file__).parent)\\n    from pricing.ga_events import render_events\\n    render_events()\\n    footer()\\n    st.stop()\\nst.caption('Historical comparison tools retain their own model names and assessment dates. They are not the current XGBoost calculator.')\\nst.markdown('''<div style=\\\"background:linear-gradient(110deg,#251b39,#5b43bd);color:#fff;border-radius:22px;padding:22px 26px;margin:18px 0;border:1px solid #c6baf5\\\">\\n<strong style=\\\"color:#dfff92;font-size:1.2rem\\\">🚙 Rare car? Meet the family tree.</strong><br>\\nAn uncommon make or trim has fewer close comparisons. Explore the separate hierarchical asking and wholesale estimates, their historical ranges, and how similar cars lend evidence.\\n</div>''',unsafe_allow_html=True)\\nif st.button('Explore rare-car estimates and uncertainty ↗',type='primary',key='rare_car_entry'):\\n    st.query_params['hierarchy']='1'\\n    st.session_state['_navigate_to']='🌳 Hierarchical model'\\n    st.rerun()\\n\\nfrom pricing.analytics import render_privacy, record_price\\nrender_privacy()\\nfrom pricing.dataset_sources import render_sources\\nfrom pricing.model_method_ui import render_methods\\nwith st.sidebar:\\n    st.markdown('## Nerd mode, unlocked.')\\n    st.caption('Model controls, real scores and receipts. The science has its own parking space.')\\nfrom marketbridge.engine import best_asking_bundle\\n# Prefer a completed full-data deployment once installed; serve the real assessment meanwhile.\\ninstalled_minilm=Path('models/minilm-assessment')\\nfor candidate in [Path('models/minilm-cleanlab'),Path('artifacts/car-price-studio-cleanlab'),Path('models/minilm-full'),Path('artifacts/car-price-studio-full'),installed_minilm]:\\n    manifest_file=candidate/'manifest.json'\\n    if manifest_file.exists():\\n        candidate_manifest=json.loads(manifest_file.read_text())\\n        if (candidate_manifest.get('status')=='ready' and\\n            candidate_manifest.get('pipeline')=='fine-tuned-minilm-l6+lightgbm' and\\n            candidate_manifest.get('outlier_filter',{}).get('algorithm') in ['Cleanlab','IsolationForest']):\\n            installed_minilm=candidate\\n            break\\nminilm_record=json.loads((installed_minilm/'manifest.json').read_text()) if (installed_minilm/'manifest.json').exists() else {}\\nminilm_method=minilm_record.get('outlier_filter',{}).get('algorithm','none')\\nminilm_label='MiniLM + '+('Cleanlab' if minilm_method=='Cleanlab' else 'Isolation Forest (legacy)')+' + LightGBM'\\nchoices=[minilm_label,'Best trained ensemble','Unfiltered trained ensemble','Trained tabular baseline']\\nfiltered=Path('models/robust-asking-isolation')\\nif (filtered/'manifest.json').exists():choices.append('Isolation Forest trained ensemble')\\ncleanlab_ensemble=Path('models/robust-asking-cleanlab')\\nif (cleanlab_ensemble/'manifest.json').exists() and json.loads((cleanlab_ensemble/'manifest.json').read_text()).get('status')=='ready':choices.append('Cleanlab trained ensemble')\\naft_path=Path('models/price-model-suite/ask')\\naft_label='MiniLM + Cleanlab + XGBoost AFT · original'\\naft_ready=(aft_path/'manifest.json').exists() and json.loads((aft_path/'manifest.json').read_text()).get('status')=='ready'\\nif aft_ready:choices.insert(0,aft_label)\\nfrom pricing.residual_ui import ready as robust_aft_ready,model_root\\n_default_root=model_root(Path('.'))\\nrobust_aft_label=('MiniLM + CatBoost AFT' if _default_root.name in ['minilm-catboost-aft','iterative-catboost'] else 'CatBoost AFT' if _default_root.name=='catboost-aft' else 'XGBoost AFT')+(' · five-stage cleaning (default)' if _default_root.name=='iterative-catboost' else ' · residual-trimmed (default)')\\nif robust_aft_ready(Path('.')) and 'CatBoost' not in robust_aft_label:choices.insert(0,robust_aft_label)\\ntabular_catboost_label='CatBoost AFT · tabular comparison'\\n\\niterative_quantile_label='MiniLM + CatBoost quantile 0.5 · five-stage comparison'\\n\\nmode=st.sidebar.selectbox('Pricing model',choices,index=choices.index('Trained tabular baseline'),key='pricing_model')\\nlocations={iterative_quantile_label:Path('models/iterative-catboost/ask-quantile'),tabular_catboost_label:Path('models/catboost-aft/ask'),robust_aft_label:model_root(Path('.'))/'ask',aft_label:aft_path,'Cleanlab trained ensemble':cleanlab_ensemble,'Best trained ensemble':best_asking_bundle(Path('.')),\\n           minilm_label:installed_minilm,\\n           'Isolation Forest trained ensemble':filtered,\\n           'Unfiltered trained ensemble':Path('models/robust-asking'),\\n           'Trained tabular baseline':Path('models/studio-baseline')}\\npath=Path(os.environ.get('PRICING_MODEL_DIR',str(locations[mode])))\\nready=(path/'manifest.json').exists()\\nselected_manifest=json.loads((path/'manifest.json').read_text()) if ready else {}\\nuses_text=selected_manifest.get('pipeline')=='fine-tuned-minilm-l6+lightgbm' or (selected_manifest.get('pipeline') in ['modest-model-suite','catboost-aft','catboost-log-quantile'] and selected_manifest.get('text_feature',False))\\nwith st.sidebar:\\n    st.caption('Historical comparison model only. Current XGBoost properties are in The science.')\\nif not ready:\\n    st.warning('The selected historical model is unavailable. Choose an installed model in the sidebar.')\\n\\n@st.cache_resource\\ndef _get_pipeline(location,version):\\n    from pricing.inference import PricePipeline\\n    return PricePipeline(location)\\n\\ndef get_pipeline(location):\\n    file=Path(location)/'manifest.json'\\n    return _get_pipeline(location,file.stat().st_mtime_ns)\\n\\nst.markdown('<div id=\\\"studio-calculator\\\"></div>',unsafe_allow_html=True)\\nif _workspace=='🌳 Hierarchical model':\\n    from pricing.hierarchical_ui import render as render_hierarchical\\n    render_hierarchical(Path(__file__).parent)\\nif _workspace=='🧹 Outlier lab':\\n    from pricing.outlier_lab import render as render_outlier_lab\\n    render_outlier_lab(Path(__file__).parent)\\nif _workspace=='🧪 Model lab':\\n    from pricing.suite_ui import render\\n    render(Path(__file__).parent)\\nif _workspace=='↔ Two-market garage':\\n    from marketbridge.ui import render_comparison\\n    render_comparison(Path(__file__).parent)\\nif _workspace=='🚗 Price my car':\\n    from pricing.price_meaning import render_market_guide,render_market_price\\n    render_market_guide()\\n    from pricing.current_value import (clock_controls,current_transport,DateAdjustedAsking,\\n        render_market_clock,render_adjustment,render_time_evidence)\\n    valuation_date,allow_newer_auction=clock_controls()\\n    for key,default in {'year':2015,'manufacturer':'Toyota','model':'Corolla SE','odometer':95000,'state':'ca'}.items():\\n        st.session_state.setdefault('vehicle_'+key,default)\\n    editor,receipt=st.columns([1.65,1],gap='large')\\n    with editor:\\n        with st.container(key='vehicle_editor'):\\n            section('01 / The test drive','Meet your next number.')\\n            st.caption('Try a real advert or bring your own car. Every detail is editable.')\\n            from pricing.description_examples import render_examples\\n            render_examples(uses_text)\\n            with st.form('vehicle'):\\n                a,b,c=st.columns(3)\\n                year=a.number_input('Year',key='vehicle_year',min_value=1900,max_value=2021,value=None)\\n                make=b.text_input('Make',key='vehicle_manufacturer',value=None)\\n                model=c.text_input('Model / trim',key='vehicle_model',value=None)\\n                a,b,c=st.columns(3)\\n                miles=a.number_input('Mileage (miles)',key='vehicle_odometer',min_value=0,max_value=2000000,value=None,step=1000)\\n                state=b.text_input('US state abbreviation',key='vehicle_state',value=None,max_chars=2)\\n                body=c.selectbox('Body type',['sedan','SUV','truck','pickup','hatchback','coupe','wagon','van','convertible','other','unknown'],key='vehicle_type')\\n                with st.expander('Fine-tune the details · condition, engine & more'):\\n                    a,b,c=st.columns(3)\\n                    condition=a.selectbox('Condition',['unknown','excellent','good','fair','like new','new','salvage'],key='vehicle_condition')\\n                    fuel=b.selectbox('Fuel',['gas','diesel','hybrid','electric','other','unknown'],key='vehicle_fuel')\\n                    transmission=c.selectbox('Transmission',['automatic','manual','other','unknown'],key='vehicle_transmission')\\n                    a,b=st.columns(2)\\n                    drive=a.selectbox('Drive',['unknown','fwd','rwd','4wd'],key='vehicle_drive')\\n                    title=b.selectbox('Title status',['clean','rebuilt','salvage','lien','missing','parts only','unknown'],key='vehicle_title_status')\\n                    cylinders=a.selectbox('Cylinders',['unknown','3 cylinders','4 cylinders','5 cylinders','6 cylinders','8 cylinders','10 cylinders','12 cylinders','other'],key='vehicle_cylinders')\\n                    color=b.selectbox('Paint color',['unknown','white','black','silver','grey','blue','red','green','brown','yellow','orange','purple','custom'],key='vehicle_paint_color')\\n                st.markdown('**02 / The backstory**')\\n                notes=st.text_area('Seller description — free text',key='seller_description',height=165,max_chars=MAX_CHARACTERS,disabled=not uses_text,\\n                    placeholder='Service history? Fresh tyres? That mysterious rattle? Tell the model the whole story.' if uses_text else 'Choose a MiniLM model in the sidebar to include your description.')\\n                submitted=st.form_submit_button('Estimate asking price',disabled=not ready,type='primary',use_container_width=True)\\n            st.caption('Your mileage and condition are interpreted at the selected valuation date. Historical models are adjusted for vehicle age and market movement; completed-sale values remain unverified.')\\n    if submitted:\\n        if len(notes)>8000:\\n            st.warning('Please keep the description within 8,000 characters.')\\n        else:\\n            fields=dict(year=year,manufacturer=make,model=model,odometer=miles,condition=condition,\\n                fuel=fuel,transmission=transmission,drive=drive,type=body,title_status=title,\\n                cylinders=cylinders,paint_color=color,state=state)\\n            try:\\n                with st.spinner('Interviewing the trees. They have opinions…'):\\n                    p=get_pipeline(str(path)).predict(notes,fields,explain=True)\\n                st.session_state['last_explained_price']=(str(path),p,fields,notes)\\n                import uuid\\n                st.session_state['_price_request_id']=str(uuid.uuid4())\\n            except Exception as exc:\\n                st.error(f'Model unavailable: {exc}')\\n    saved=st.session_state.get('last_explained_price')\\n    dated_result=dated_pipeline=transport=None\\n    dated_receipts={};date_error=None;refresh_error=None\\n    st.session_state.pop('last_displayed_price',None)\\n    if saved and saved[0]==str(path):\\n        try:\\n            with st.spinner('Moving the price clock to your selected date…'):\\n                transport,refresh_error=current_transport(Path(__file__).parent)\\n                dated_pipeline=DateAdjustedAsking(get_pipeline(str(path)),transport,valuation_date)\\n                dated_result=dated_pipeline.adjust(saved[1],saved[2])\\n                dated_receipts['ask']=dated_result['time_adjustment']\\n                st.session_state['last_displayed_price']=(saved[0],dated_result,saved[2],saved[3])\\n            request=st.session_state.get('_price_request_id','')\\n            record_price('ask',dated_result['price'],saved[2],mode+' · date adjusted','calculator',str(valuation_date),request+':ask:'+str(valuation_date))\\n        except (ValueError,OSError,KeyError) as exc:\\n            date_error=str(exc)\\n    with receipt:\\n        with st.container(key='price_receipt'):\\n            if dated_result:\\n                result=dated_result;car=saved[2]\\n                section('03 / Your price receipt','The numbers are in.')\\n                st.caption(f\\\"{car['year']} {car['manufacturer']} {car['model']} · {car['odometer']:,} miles\\\")\\n                render_market_price('ask',result['price'],valuation_date,scenario=True)\\n                render_adjustment(dated_receipts['ask'])\\n                st.caption('Point estimate only. No validated individual prediction interval is available.')\\n            elif date_error:\\n                st.error('Date-adjusted asking estimate unavailable: '+date_error)\\n                st.caption('No historical price is substituted under today’s date. Change the date or vehicle assumptions to a supported scenario.')\\n            else:empty_receipt()\\n        if saved and saved[0]==str(path):\\n            with st.container(key='auction_receipt'):\\n                try:\\n                    if transport is None:raise ValueError('The date-adjustment layer is unavailable.')\\n                    from pricing.residual_ui import bid_folder,load\\n                    bid_path=bid_folder(Path(__file__).parent)\\n                    bid,_,_=load(str(bid_path),(bid_path/'manifest.json').stat().st_mtime_ns)\\n                    from marketbridge.time_engine import today\\n                    r=transport.estimate(bid,'',saved[2],valuation_date,'bid',allow_newer_auction,as_of=today())\\n                    dated_receipts['bid']=r\\n                    render_market_price('bid',r['price'],valuation_date,scenario=True)\\n                    render_adjustment(r)\\n                    request=st.session_state.get('_price_request_id','')\\n                    record_price('bid',r['price'],saved[2],'date-adjusted auction','calculator',str(valuation_date),request+':bid:'+str(valuation_date)+':'+str(allow_newer_auction))\\n                except (ValueError,OSError,KeyError) as exc:\\n                    st.warning('Date-adjusted auction estimate unavailable: '+str(exc))\\n                    if saved[2].get('year',0)>2015 and not allow_newer_auction:\\n                        st.caption('The optional newer-generation assumption is in “Valuation date & auction coverage” above. You have disabled it; enable it for an explicitly labelled newer-generation scenario.')\\n            st.info('Same valuation date, different markets. The gap is not dealer profit or a promised discount.')\\n            if dated_result:\\n                from pricing.deal_detective import open_share\\n                st.button('📣 Share my price · image, link & group-chat fuel',on_click=open_share,key='open_share')\\n            st.caption('Open 📅 Value over time for the interactive timeline and mileage scenarios.')\\n            if saved[1].get('predicted_text_price') is not None:\\n                with st.expander('What did the description contribute?'):\\n                    st.metric('Description-price feature',f\\\"${saved[1]['predicted_text_price']:,.0f}\\\")\\n                    st.caption('MiniLM’s description-only scalar enters the asking model alongside vehicle facts. It is not an independent offer or a word-level explanation.')\\n        else:\\n            st.markdown('<div class=\\\"garage-science-note\\\"><strong>Curious what moves the price?</strong><br>After estimating, explore feature contributions, mileage scenarios and all six explanation graphs below.</div>',unsafe_allow_html=True)\\n    if saved and saved[0]==str(path):\\n        report={\\n            'valuation_date':str(valuation_date),\\n            'vehicle_facts':saved[2],\\n            'market_estimates':{side:{\\n                'estimated_price_usd':round(r['price'],2),\\n                'vehicle_age_years':round(r['age'],2),\\n                'age_multiplier':round(r['age_factor'],4),\\n                'market_multiplier':round(r['market_factor'],4),\\n                'historical_anchor_usd':round(r['anchor_price_reference_usd'],2),\\n                'market_index_status':r['market'],\\n                'pooled_depreciation':not r['model_known_to_curve'],\\n                'newer_generation_analogue':r['generation_analogue']\\n            } for side,r in dated_receipts.items()},\\n            'unavailable_markets':[s for s in ['ask','bid'] if s not in dated_receipts],\\n            'market_source':'BLS/FRED CUUR0000SETA02',\\n            'latest_observed_month':transport.clock.meta['latest_observation'] if transport else None,\\n            'scope':'Experimental date-adjusted estimates; no validated current-car prediction interval.'\\n        }\\n        from pricing.valuation_story import extend_report\\n        report=extend_report(report,Path(__file__).parent,saved[2],saved[1],dated_receipts,transport,path,locals().get('bid_path'))\\n        with st.container(key='story_receipt'):\\n            from pricing.bart_summary import render_story\\n            render_story(saved[2],saved[3],valuation=report)\\n        if dated_result:\\n            render_market_clock(transport,valuation_date,refresh_error)\\n            render_time_evidence(transport,dated_receipts)\\n            from pricing.text_attribution_ui import render_text_attribution\\n            render_text_attribution(dated_result,saved[2],saved[3],dated_pipeline)\\n        st.divider()\\n        section('The receipts / Explainable machine learning','Pop the bonnet. Question everything.')\\n        st.caption('The current-date price and phrase effects are above. The historical model diagnostics below explain the original May 2021 anchor, before time adjustment.')\\n        with st.expander('Historical base-model diagnostics · May 2021, before time adjustment'):\\n            st.metric('Original historical asking anchor · May 2021',f\\\"${saved[1]['price']:,.0f}\\\")\\n            from pricing.explanations import render_explanation\\n            render_explanation(saved[1],saved[2],saved[3],get_pipeline(str(path)))\\n            from pricing.explanation_ui import render_visual_explanations\\n            render_visual_explanations(saved[1],saved[2],saved[3],get_pipeline(str(path)))\\nif _workspace=='📅 Value over time':\\n    from pricing.time_ui import render_time_studio\\n    time_saved=st.session_state.get('last_explained_price')\\n    if time_saved and time_saved[0]!=str(path):time_saved=None\\n    render_time_studio(Path(__file__).parent,time_saved,get_pipeline(str(path)) if time_saved else None)\\nif _workspace=='🧠 The science':\\n    if _default_root.name=='iterative-catboost':\\n        st.success('Active default: five-stage CatBoost cleaning; MiniLM + asking AFT and wholesale log-median quantile 0.5. Full model card and all measured trade-offs are in Outlier lab. The older methods described below remain comparison experiments.')\\n    if _default_root.name!='iterative-catboost':st.write('The asking default combines MiniLM description regression with CatBoost normal AFT. The auction default is tabular CatBoost quantile 0.5 on log prices, fitted after a separate quantile-residual cleaner removes the highest-residual 25% per original phase. CatBoost handles categorical labels natively and uses exact observed dollar bounds, with an internal log-price likelihood. Ask preserves its existing highest-residual quartile plus OutlierTree masks. Bid uses its new quantile-residual top-quarter cut only, without additional OutlierTree flags. Filtered test scores are optimistic selected-cohort results; original-test diagnostics are reported too. The MiniLM + CatBoost default includes the dynamic description-price feature; the earlier tabular-only CatBoost model is a comparison baseline. Auction data contain no descriptions, so auction CatBoost remains tabular. Only its cleaner can optionally use an IMR fitted from a genuine sold/unsold listing population; such data are currently unavailable. Earlier models remain available for comparison.')\\n    st.subheader('A pricing committee with thousands of small opinions')\\n    st.write('LightGBM learns lots of small decision trees, each correcting earlier mistakes. Huber loss softens the influence of large errors: one wildly ambitious seller does not get to chair the committee. The fitted tree count and exact drivers appear after an estimate.')\\n    st.write('Make and model enter LightGBM as ordinary categorical fields. Their transformer and separate neural price head have been removed.')\\n    st.write('The trained ensembles average regularized LightGBM models with age-adjusted CarBids features. New filtered training uses Cleanlab regression on vehicle facts and observed training log prices. Its internal cross-validation and uncertainty estimates identify suspected price-label errors. Historical Isolation Forest bundles keep their original names and scores. In those older benchmarks validation/test remained unfiltered. The requested CatBoost refit filters both and labels its scores accordingly. The original unfiltered ensemble remains selectable. The best-model choice uses the filtered model only if its recorded assessment passed. Benchmark results are in Evaluation.')\\n    st.write('The MiniLM workflow fine-tunes sentence-transformers/all-MiniLM-L6-v2 on descriptions and log prices. Three-fold predictions create predicted_text_price without using each predicted row’s target in its fitting model.')\\n    st.write('Cleanlab audits training labels from structured vehicle fields, excluding the text-price stacking feature to avoid indirect target leakage. It chooses a suspected-noise fraction internally; flags are not verified errors. Validation and test are unfiltered. Huber LightGBM combines retained training prices with the structured fields. The installed MiniLM assessment model runs on CPU and dynamically reads your description; GPU training is not needed to use it.')\\n    if minilm_record.get('outlier_filter',{}).get('algorithm')=='Cleanlab':\\n        st.write('The selectable MiniLM + Cleanlab baseline uses a modest Huber LightGBM with library-default statistical parameters (100 trees) and a log1p price target. MiniLM produces a dynamic dollar-price feature. Separate training-only text predictions protect the assessment; the completed full-data text head serves deployment. Make and model remain categorical fields.')\\n    else:\\n        st.write('The legacy assessment used standardized dollar targets in its selected Huber LightGBM. MiniLM itself learned standardized log1p prices. Its inverse-transformed dollar estimate becomes predicted_text_price.')\\n    st.write('The complete raw database is scanned before eligibility checks and deduplication. The eligible sample is split chronologically 70/15/15. Historical 2021 asking prices are not completed-sale prices or current valuations.')\\nif _workspace=='📊 Evaluation':\\n    from pricing.hierarchy_sparse_studio import scorecard\\n    scorecard(Path(__file__).parent,details=True)\\n    st.divider()\\n    st.subheader('Historical experiments · different architectures and cohorts')\\n    from pricing.evaluation_ui import render_model_comparison\\n    render_model_comparison()\\n    if (path/'evaluation.json').exists() and ready:\\n        e=json.loads((path/'evaluation.json').read_text())\\n        if e.get('ensemble_members'):\\n            st.info(f\\\"Regularized ensemble: {e['ensemble_members']} members; promoted: {e['promoted']}\\\");st.json(e['test'])\\n            st.write({k:e[k] for k in ['train_rows','validation_rows','test_rows']})\\n            st.caption(e['test_note'])\\n            if e.get('outlier_filter',{}).get('method') in ['Cleanlab','IsolationForest']:\\n                f=e['outlier_filter']\\n                st.write(f\\\"{f['method']} retained {f['retained_rows']:,} of {f['input_rows']:,} training cars; removed {f['removed_fraction']:.1%}.\\\")\\n                st.caption('Cleanlab uses observed training prices as labels; legacy Isolation Forest used predictors only. Suspected issues can be legitimate cars. Validation and test remain unfiltered.')\\n                st.dataframe([{'model':'Unfiltered reference',**e['baseline']['test']},{'model':f[\\\"method\\\"]+' ensemble',**e['test']}],hide_index=True)\\n                st.json(f,expanded=False)\\n                if not e['promoted']:st.info('This is the completed filtered experiment. The Best trained ensemble option selects the unfiltered ensemble because its benchmark errors are lower.')\\n            st.download_button('Download selected ensemble assessment',json.dumps(e,indent=2),'asking-ensemble-evaluation.json','application/json')\\n            with st.expander('All training candidates · technical details'):st.json(e['grid'])\\n        elif selected_manifest.get('training_regime') in ['five-stage-catboost-residual','residual-trimmed-robust-xgb','residual-trimmed-catboost-aft','residual-trimmed-minilm-catboost-aft']:\\n            from pricing.residual_ui import render_assessment\\n            render_assessment(Path('.'))\\n        elif selected_manifest.get('pipeline')=='modest-model-suite':\\n            st.subheader('Default asking AFT · chronological held-out assessment')\\n            st.json(e['models']['xgb_aft_normal']['test'])\\n            st.write(e['rows'])\\n            st.caption(e['evaluation'])\\n            st.info('AFT is preferred by recorded RMSE on both market datasets. Compare all models, MAE trade-offs, Spearman and Ridge calibration in New model laboratory.')\\n        elif e.get('mode')=='tabular_baseline':\\n            st.info(e['label']);st.json(e['test'])\\n            st.write({k:e[k] for k in ['train_rows','validation_rows','test_rows','eligible_rows']})\\n            st.write('Final deployment refit rows:',e.get('deployment_refit_rows',e['train_rows']))\\n            st.caption(e.get('assessment_note','Chronological held-out assessment.'))\\n        else:\\n            st.write(e['rows']);st.json(e['stacked'])\\n            if selected_manifest.get('deployment_scope')=='completed-chronological-assessment':\\n                st.caption(selected_manifest['assessment_note'])\\n                st.text(f\\\"Description-only test MAE: ${e['description_only']['mae_usd']:,.0f} · MiniLM + LightGBM test MAE: ${e['stacked']['mae_usd']:,.0f}.\\\")\\n                st.info('This is the historical MiniLM comparison model, not the current studio default. Its filter is recorded in the model manifest. The other trained models remain selectable for comparison. The recorded assessment above belongs to these installed weights; the full-data refit has not finished yet.')\\n                st.download_button('Download MiniLM assessment',json.dumps(e,indent=2),'minilm-assessment.json','application/json')\\n        if selected_manifest.get('pipeline') in ['modest-model-suite','catboost-aft','catboost-log-quantile']:\\n            st.caption('Point estimate only. Neither the AFT distribution nor quantile loss provides a validated current-car prediction interval here.')\\n        elif selected_manifest.get('band80_log_radius') is None and uses_text:\\n            st.caption('The original evaluation recorded interval coverage, but its calibration radius was not persisted. This installation serves point estimates only.')\\n        elif 'band80_test_coverage' in e:st.write(f\\\"Indicative 80% band test coverage: {e['band80_test_coverage']:.1%}\\\")\\n        else:st.caption('The ensemble band is calibrated on historical validation residuals; no individual or future-market coverage guarantee is claimed.')\\n    else:st.info('This mode has no completed evaluation. Train MiniLM to enable it; baseline scores do not apply.')\\n\\nif _workspace=='🕵️ Deal Detective':\\n    from pricing.deal_detective import render as render_detective\\n    from pricing.deal_runtime import current_callbacks\\n    ask_callback,bid_callback,callback_model=current_callbacks(Path(__file__).parent)\\n    render_detective(ask_callback,bid_callback,callback_model)\\n\\nfrom pricing.ga_events import render_events\\nrender_events()\\nfooter()\\n\\n# Inspector release a7cb5bd: forecast-aware query context, price-free SVD.\\n\\n\",\"scripts/check_doc2vec_ui.py\":\"\\\"\\\"\\\"Verify the installed MiniLM route and a real five-rating shortlist.\\\"\\\"\\\"\\nfrom pathlib import Path\\nfrom streamlit.testing.v1 import AppTest\\nimport json,hashlib\\nroot=Path('.')\\nmeta=json.loads((root/'data/merchant-discovery-minilm/manifest.json').read_text())\\nassert 'MiniLM' in meta['semantic_model']\\nsource=(root/'pricing/merchant_discovery_ui.py').read_text()\\nassert 'merchant_text_method' not in source\\nassert \\\"data/merchant-discovery-minilm\\\" in source\\napp=AppTest.from_string(\\\"from pathlib import Path\\\\nfrom pricing.merchant_discovery_ui import render\\\\nrender(Path('.'))\\\",default_timeout=120).run()\\nassert not app.exception,app.exception\\nassert not any(x.label=='Text matching model' for x in app.radio)\\nfor i,widget in enumerate(app.pills):\\n    widget.set_value(4 if i==0 else 1)\\napp.run()\\napp.button(key='merchant_find').click().run(timeout=120)\\nassert not app.exception,app.exception\\nassert any('Your shortlist' in x.value for x in app.markdown)\\nversion=hashlib.sha256((root/'data/merchant-discovery-minilm/manifest.json').read_bytes()).hexdigest()[:12]\\nresult=app.session_state['merchant_result_'+version]\\nassert len(set(result['positions']))==10\\nprint('MiniLM default: five ratings submitted; ten distinct results rendered; no TF-IDF selector.')\\n\",\"MERCHANT_DISCOVERY.md\":\"# Merchant + Meaning discovery\\nA separate Drive Chemistry engine, enabled only after its verified catalogue is installed.\\n\\n## Business behavior\\nFive diverse real cars collect direct reactions. Every liked car supplies a separate semantic interest; dislikes subtract graded evidence instead of vetoing entire clusters. The shortlist is scored highest-first. Rating results and resubmitting refines the session, excluding already-rated cars. A historical asking-price limit is optional and explicit. Price displays are historical and not current valuations.\\n\\nMerchant groups require an automotive organization mention and one corroborating non-platform domain. Conflicting organization identities remain unresolved. These are inferred candidates, not verified businesses; legal identity, ownership and merchant expertise have not been audited.\\n\\nThe current extraction resolved zero merchant candidates and zero linked adverts, so the inventory branch has insufficient support and recommendations currently use description semantics alone. Inventories can connect through shared vehicle-type attributes rather than isolated advert IDs. This is a hypothesis about commercial assortment, not customer purchase preference. Unknown identities never exclude a car.\\n\\n## Offline implementation\\nRecover canonical original descriptions for retained reference rows, checking row IDs and prices. The packaged baseline uses dslim/bert-base-NER; a separate GLiNER extraction job is in progress. That baseline extracts organization mentions. Only automotive-business candidates with a supporting domain are resolved; lenders/platforms are excluded conservatively. Canonicalization ignores punctuation and common company suffixes. The first version does not resolve every address, alias or corporate branch.\\n\\nVehicle semantics suppress resolved seller names and contact/financing lines. The default uses all-MiniLM-L6-v2 embeddings of 110,832 retained descriptions, with a 256-token limit and a 96-dimensional truncated SVD projection. Stored document vectors are normalized offline; serving needs no text model. TF-IDF is removed from this engine’s selector and is not a fallback. Doc2Vec is no longer the default.\\n\\nMerchant inventory counts use shared make, body and make/model columns. Row normalization reduces dealer-size effects; inverse merchant frequency reduces ubiquitous attributes. TruncatedSVD supplies up to 32 inventory-association dimensions. No user feedback labels are invented for this model.\\n\\nThe initial hybrid uses 80% semantic and 20% inventory association where available, with a graded dislike penalty of 35%. Unavailable inventory falls back to semantics. Each liked vehicle contributes separately using its rating strength. Up to 500 candidates enter diversity selection, with at most two exact make/model types. No same-make restriction applies. These weights are declared baselines, not learned optima.\\n\\n## Verification and limits\\nUnit checks cover platform/lender ambiguity, preference ordering, explicit budget filtering and exclusion of rated cars. Each initial seed is tested as the sole like against four dislikes and must return ten distinct cars. A real Streamlit five-rating/submit/shortlist-render test gates publication.\\n\\nThere is no independently labelled relevance benchmark or manually audited entity precision yet. Existing canonical preparation has already deduplicated text/VINs, so this first catalogue is not an untouched original-advert archive. Dealer co-stock affinity is not evidence that a shopper wants the same cars. No fraud, transaction or conversion claims are made.\\n\\nExisting KMeans/HDBSCAN experiments remain available. Activation requires a manifest containing the passed UI check. Serving artifacts are independent; the main pricing models are unchanged.\\n\"}")
